package sfz.txn.l08.demo

/** One item with the metadata a DynamoDB storage node keeps next to it: its last write and the transaction preparing it. */
private class Item(val key: String, var balance: Long) {
    var lastWrite = 0L
    var ongoing: String? = null
}

/** One action of a transaction: change [key] by [delta], if [condition] holds on the current balance. */
private class Action(val key: String, val delta: Long, val condition: (Long) -> Boolean = { true })

private class Tx(val id: String, val timestamp: Long, val actions: List<Action>)

/**
 * A model of the two-phase protocol in "Distributed Transactions at Scale in Amazon DynamoDB"
 * (USENIX ATC 2023): a coordinator prepares every item, then commits or cancels. Each item lives
 * on its own storage node, as if in its own partition. DynamoDB Local runs transactions one at a
 * time, so it can't show a conflict; this model can.
 */
fun main() {
    val items = listOf(Item("A-1001", 10_000), Item("A-2002", 5_000), Item("A-3003", 0)).associateBy { it.key }
    val ledger = mutableMapOf<String, String>() // the coordinators' durable record: transaction id -> decision

    fun log(tx: String, what: String) = println("%-3s %s".format(tx, what))

    /** Phase 1 on one item: the checks from the paper's prepare listing. */
    fun prepare(tx: Tx, a: Action): Boolean {
        val item = items.getValue(a.key)
        val verdict = when {
            item.ongoing != null -> "REJECTED: ${item.ongoing} is in flight on this item"
            tx.timestamp <= item.lastWrite -> "REJECTED: older than the item's last write"
            !a.condition(item.balance) -> "REJECTED: condition failed (balance ${item.balance})"
            else -> null
        }
        log(tx.id, "prepare ${a.key}: ${verdict ?: "accepted"}")
        if (verdict == null) item.ongoing = tx.id // the item is now held for this transaction
        return verdict == null
    }

    fun commit(tx: Tx) {
        for (a in tx.actions) {
            val item = items.getValue(a.key)
            val before = item.balance
            item.balance += a.delta
            item.lastWrite = tx.timestamp
            item.ongoing = null
            log(tx.id, "commit  ${a.key}: $before -> ${item.balance}")
        }
        ledger[tx.id] = "COMPLETED"
    }

    /** One coordinator running one transaction. [crashBeforeCommit] stops it after it has decided. */
    fun run(tx: Tx, crashBeforeCommit: Boolean = false): Boolean {
        ledger[tx.id] = "PREPARING"
        val prepared = mutableListOf<Action>()
        for (a in tx.actions) {
            if (!prepare(tx, a)) {
                prepared.forEach { items.getValue(it.key).ongoing = null; log(tx.id, "cancel  ${it.key}") }
                ledger[tx.id] = "CANCELLED"
                log(tx.id, "-> cancelled; nothing was written")
                return false
            }
            prepared += a
        }
        ledger[tx.id] = "COMMITTING" // the decision is durable before any item changes
        if (crashBeforeCommit) {
            log(tx.id, "-> coordinator crashes after deciding COMMIT; both items stay held")
            return false
        }
        commit(tx)
        log(tx.id, "-> committed")
        return true
    }

    fun transfer(id: String, ts: Long, from: String, to: String, amount: Long) =
        Tx(id, ts, listOf(Action(from, -amount) { it >= amount }, Action(to, amount)))

    println("== two transfers out of A-1001 collide")
    val t1 = transfer("T1", 100, "A-1001", "A-2002", 3_000)
    // T2 moves 50.00 from A-1001 to A-3003, and happens to list the credit first
    val t2 = Tx("T2", 101, listOf(Action("A-3003", 5_000), Action("A-1001", -5_000) { it >= 5_000 }))
    // T1 prepares A-1001 first; T2 prepares A-3003, then reaches A-1001 while T1 holds it
    prepare(t1, t1.actions[0])
    run(t2)
    prepare(t1, t1.actions[1])
    ledger["T1"] = "COMMITTING"
    commit(t1)
    log("T1", "-> committed")
    println("T2 gets TransactionConflict. The SDK doesn't retry a cancelled transaction: your code does,")
    println("with a new timestamp and the same idempotency key, after a short backoff.")
    run(Tx("T2", 105, t2.actions))

    println()
    println("== a coordinator dies between its decision and the commits")
    run(transfer("T3", 110, "A-2002", "A-1001", 2_000), crashBeforeCommit = true)
    run(transfer("T4", 111, "A-1001", "A-3003", 1_000))
    println("recovery manager scans the ledger: ${ledger.filterValues { it == "COMMITTING" }.keys} decided but not completed")
    commit(transfer("T3", 110, "A-2002", "A-1001", 2_000))
    log("T3", "-> completed by a new coordinator")
    run(transfer("T4", 112, "A-1001", "A-3003", 1_000))

    println()
    println("balances: " + items.values.joinToString { "${it.key} ${it.balance}" } + "  (total ${items.values.sumOf { it.balance }})")
}

// Lesson txn-08: two transactions collide on one document, then an outside write waits and a
// transaction outlives its time limit. Run against env/mongo.yml (a one-member replica set):
//   docker compose -f env/mongo.yml exec mongo mongosh sfz --quiet /sfz/nosql-10-transactions.js
db.accounts.drop()
db.accounts.insertMany([{ _id: "A-1001", balanceMinor: 10000 }, { _id: "A-2002", balanceMinor: 5000 }])

// two sessions, two transactions, each with its own snapshot
const opts = { readConcern: { level: "snapshot" }, writeConcern: { w: "majority" } }
const s1 = db.getMongo().startSession(), a1 = s1.getDatabase("sfz").accounts
const s2 = db.getMongo().startSession(), a2 = s2.getDatabase("sfz").accounts
s1.startTransaction(opts)
s2.startTransaction(opts)
print("tx1 reads A-1001:", a1.findOne({ _id: "A-1001" }).balanceMinor)
print("tx2 reads A-1001:", a2.findOne({ _id: "A-1001" }).balanceMinor)

// tx1 debits 30.00 first; tx2 then tries to debit 80.00 from the same document
print("tx1 debit 3000:", a1.updateOne({ _id: "A-1001", balanceMinor: { $gte: 3000 } }, { $inc: { balanceMinor: -3000 } }).modifiedCount)
try {
  a2.updateOne({ _id: "A-1001", balanceMinor: { $gte: 8000 } }, { $inc: { balanceMinor: -8000 } })
} catch (e) {
  print("tx2 debit 8000:", e.codeName, JSON.stringify(e.errorLabels))
}
print("outside, before tx1 commits:", db.accounts.findOne({ _id: "A-1001" }).balanceMinor)
a1.updateOne({ _id: "A-2002" }, { $inc: { balanceMinor: 3000 } })
s1.commitTransaction()
print("outside, after tx1 commits:", db.accounts.findOne({ _id: "A-1001" }).balanceMinor)

// the retry is a NEW transaction with a new snapshot: it sees 7000, and its condition is false
s2.abortTransaction()
s2.startTransaction(opts)
print("tx2 retry reads A-1001:", a2.findOne({ _id: "A-1001" }).balanceMinor)
print("tx2 retry debit 8000:", a2.updateOne({ _id: "A-1001", balanceMinor: { $gte: 8000 } }, { $inc: { balanceMinor: -8000 } }).modifiedCount)
s2.abortTransaction()

// a plain write, outside any transaction, to a document an open transaction has changed: it waits
s1.startTransaction(opts)
a1.updateOne({ _id: "A-1001" }, { $inc: { balanceMinor: -100 } })
let t = Date.now()
try {
  db.runCommand({ update: "accounts", updates: [{ q: { _id: "A-1001" }, u: { $inc: { balanceMinor: -1 } } }], maxTimeMS: 2000 })
} catch (e) { print("outside write:", e.codeName, "after", Date.now() - t, "ms") }
s1.abortTransaction()

// the time limit: 60 seconds by default; set it to 5 to watch it, then put it back
print("transactionLifetimeLimitSeconds:", db.adminCommand({ getParameter: 1, transactionLifetimeLimitSeconds: 1 }).transactionLifetimeLimitSeconds)
db.adminCommand({ setParameter: 1, transactionLifetimeLimitSeconds: 5 })
s1.startTransaction(opts)
a1.updateOne({ _id: "A-1001" }, { $inc: { balanceMinor: -100 } })
sleep(12000) // a slow call to the card issuer, say
try { s1.commitTransaction() } catch (e) { print("commit after 12 s:", e.codeName) }
db.adminCommand({ setParameter: 1, transactionLifetimeLimitSeconds: 60 })
print("A-1001 at the end:", db.accounts.findOne({ _id: "A-1001" }).balanceMinor)

CREATE KEYSPACE IF NOT EXISTS payments WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};
CREATE TABLE IF NOT EXISTS payments.idempotency_keys (idem_key text PRIMARY KEY, payment_id text);

-- a plain insert, traced
TRACING ON;
INSERT INTO payments.idempotency_keys (idem_key, payment_id) VALUES ('idem-0001', 'pay-81700');

-- the same kind of insert as a lightweight transaction, traced
INSERT INTO payments.idempotency_keys (idem_key, payment_id) VALUES ('idem-c41d', 'pay-81723') IF NOT EXISTS;

-- a retry with the same key loses: [applied] = False, and the row that won
INSERT INTO payments.idempotency_keys (idem_key, payment_id) VALUES ('idem-c41d', 'pay-81799') IF NOT EXISTS;
TRACING OFF;

-- read it the linearizable way: through Paxos, at SERIAL
CONSISTENCY SERIAL;
SELECT * FROM payments.idempotency_keys WHERE idem_key = 'idem-c41d';

-- transfer 30.00 from A-1001 to A-2002: two partitions, two tables, one transaction
BEGIN TRANSACTION
  LET src = (SELECT balance_minor FROM payments.balances WHERE account_id = 'A-1001');
  SELECT src.balance_minor;
  IF src.balance_minor >= 3000 THEN
    UPDATE payments.balances SET balance_minor -= 3000 WHERE account_id = 'A-1001';
    UPDATE payments.balances SET balance_minor += 3000 WHERE account_id = 'A-2002';
    INSERT INTO payments.ledger (account_id, transfer_id, amount_minor) VALUES ('A-1001', 'txf-k-1', -3000);
    INSERT INTO payments.ledger (account_id, transfer_id, amount_minor) VALUES ('A-2002', 'txf-k-1', 3000);
  END IF
COMMIT TRANSACTION;

-- transfer 90.00: the condition is false, so nothing is written
BEGIN TRANSACTION
  LET src = (SELECT balance_minor FROM payments.balances WHERE account_id = 'A-1001');
  SELECT src.balance_minor;
  IF src.balance_minor >= 9000 THEN
    UPDATE payments.balances SET balance_minor -= 9000 WHERE account_id = 'A-1001';
    UPDATE payments.balances SET balance_minor += 9000 WHERE account_id = 'A-2002';
    INSERT INTO payments.ledger (account_id, transfer_id, amount_minor) VALUES ('A-1001', 'txf-k-2', -9000);
    INSERT INTO payments.ledger (account_id, transfer_id, amount_minor) VALUES ('A-2002', 'txf-k-2', 9000);
  END IF
COMMIT TRANSACTION;

SELECT * FROM payments.balances;
SELECT * FROM payments.ledger;

