fun <T> inTransaction(client: MongoClient, body: (ClientSession) -> T): T {
    val options = TransactionOptions.builder()
        .readConcern(ReadConcern.SNAPSHOT).writeConcern(WriteConcern.MAJORITY).build()
    client.startSession().use { session ->
        var attempt = 0
        while (true) {
            attempt++
            session.startTransaction(options)            // a fresh snapshot every attempt
            try {
                val result = body(session)
                while (true) {                            // retry ONLY the commit if its outcome is unknown
                    try { session.commitTransaction(); break }
                    catch (e: MongoException) {
                        if (!e.hasErrorLabel(MongoException.UNKNOWN_TRANSACTION_COMMIT_RESULT_LABEL)) throw e
                    }
                }
                return result
            } catch (e: MongoException) {
                if (session.hasActiveTransaction()) session.abortTransaction()
                if (!e.hasErrorLabel(MongoException.TRANSIENT_TRANSACTION_ERROR_LABEL) || attempt == 10) throw e
                Thread.sleep(10L * attempt)                // back off, then rerun reads AND writes
            }
        }
    }
}
// Retrying one statement is wrong: the transaction's earlier reads came from a snapshot that a
// conflicting commit has made stale, so every decision taken from them has to be taken again.
